    "collection": [
        {
            "title": "Predicting Protein Producibility In Filamentous Fungi",
            "authors": "Dykstra, K.; Rousu, J.; Arvas, M.",
            "author_corresponding": "Juho  Rousu",
            "author_corresponding_institution": "Aalto University",
            "doi": "10.1101/138560",
            "date": "2017-05-16",
            "version": "1",
            "type": "new results",
            "license": "cc_by",
            "category": "bioinformatics",
            "jatsxml": "https://www.biorxiv.org/content/early/2017/05/16/138560.source.xml",
            "abstract": "In this paper we study the problem of predicting the producibility of recombinant proteins in filamentous fungi, especially T. reesei, using machine learning methods. We train supervised and semi-supervised support vector machines with protein sequences, represented by their amino acid composition as well as protein family and domain information. Our results indicate, somewhat surprisingly, that quite modest amount of proteins with experimental data are required to build a state-of-the-art classifier and that additional unlabeled sequences in semi-supervised models do not bring increased predictive performance. Our experiments in cross-species prediction show that models trained for the filamentous fungus A. niger protein dataset can be generalized to predict protein producibility in T. reesei, and vice versa, without sacrificing too much accuracy, regardless of their approximately 500 millions years of divergence. However, predictors trained on E. coli and S. cerevisiae datasets gave variable performance when applied to the filamentous fungi datasets, indicating that while protein producibility prediction can be generalized accross related species, fully generic prediction tools applicable to any protein production host may not be realistic to achieve.",
            "published": "NA",
            "server": "bioRxiv"
        }
    ]
}

